import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"2Captcha Integration","description":"","frontmatter":{"prev":{"text":"Check Downloads","link":"/documentation/field-types/browser-actions/check-downloads"},"next":{"text":"Fetch Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/fetch-mail-gmail"}},"headers":[],"relativePath":"documentation/field-types/captcha-solution/2captcha.md","filePath":"documentation/field-types/captcha-solution/2captcha.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/captcha-solution/2captcha.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="twocaptcha" tabindex="-1">2Captcha Integration <a class="header-anchor" href="#twocaptcha" aria-label="Permalink to “2Captcha Integration”">​</a></h1><p>Solve online challenges automatically by integrating 2Captcha API support directly into your automation forms, with native compatibility for Google reCAPTCHA v2, Cloudflare Turnstile, and image-to-text captchas.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>2Captcha</strong> field type delegates verification challenges to human solvers and AI engines via the 2Captcha API. The extension automatically extracts site keys or image buffers, dispatches the request, tracks solving progress on an optional on-screen status bar, and inserts the solved response token or text into the target form.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Captcha Type</strong></td><td>Dropdown</td><td>Challenge type: <code>RecaptchaV2TaskProxyless</code>, <code>TurnstileTaskProxyless</code>, or <code>ImageToText</code>.</td><td>Yes</td></tr><tr><td><strong>Use Captcha API Key</strong></td><td>Toggle Switch</td><td>Enable to override global/site credentials with a field-specific key.</td><td>No</td></tr><tr><td><strong>Captcha API Key</strong></td><td>Text Input</td><td>Your 2Captcha account API secret key.</td><td>When custom key enabled</td></tr><tr><td><strong>Timeout</strong></td><td>Number Input</td><td>Maximum wait duration in minutes (recommended: <code>3</code> to <code>5</code>).</td><td>No</td></tr><tr><td><strong>Store Token in Variable</strong></td><td>Toggle Switch</td><td>Saves the returned solution token to the field&#39;s variable name.</td><td>No</td></tr><tr><td><strong>Custom Status Bar Position</strong></td><td>Toggle Switch</td><td>Relocates the on-screen solving progress bar to a specific container.</td><td>No</td></tr><tr><td><strong>Status Bar Element Selector</strong></td><td>Text Input</td><td>CSS selector where the progress bar will mount.</td><td>When custom position enabled</td></tr><tr><td><strong>Run Action After Solved</strong></td><td>Toggle Switch</td><td>Automatically triggers an action once the solution returns.</td><td>No</td></tr><tr><td><strong>Action Type</strong></td><td>Dropdown</td><td>Output action (<code>Set Token in reCAPTCHA Field</code> or <code>Set Captcha Text in Field</code>).</td><td>When action enabled</td></tr><tr><td><strong>Field Selector Address</strong></td><td>Text Input</td><td>Target input where the token or text string will be inserted.</td><td>When action enabled</td></tr></tbody></table><hr><h2 id="captcha-types" tabindex="-1">Captcha Type Configurations <a class="header-anchor" href="#captcha-types" aria-label="Permalink to “Captcha Type Configurations”">​</a></h2><h3 id="_1-google-recaptcha-v2-recaptchav2taskproxyless" tabindex="-1">1. Google reCAPTCHA v2 (<code>RecaptchaV2TaskProxyless</code>) <a class="header-anchor" href="#_1-google-recaptcha-v2-recaptchav2taskproxyless" aria-label="Permalink to “1. Google reCAPTCHA v2 (RecaptchaV2TaskProxyless)”">​</a></h3><p>Designed for Google checkbox challenges (&quot;I&#39;m not a robot&quot;):</p><ul><li><strong>Site Key</strong>: Auto-detected from <code>data-sitekey</code> attributes in the DOM, or explicitly provided via <strong>Set Custom Captcha Site Key</strong>.</li><li><strong>Action Type</strong>: <code>Set Token in reCAPTCHA Field</code></li><li><strong>Target Selector</strong>: <code>#g-recaptcha-response</code> (or custom hidden textarea).</li></ul><h3 id="_2-cloudflare-turnstile-turnstiletaskproxyless" tabindex="-1">2. Cloudflare Turnstile (<code>TurnstileTaskProxyless</code>) <a class="header-anchor" href="#_2-cloudflare-turnstile-turnstiletaskproxyless" aria-label="Permalink to “2. Cloudflare Turnstile (TurnstileTaskProxyless)”">​</a></h3><p>Designed for Cloudflare managed challenge widgets:</p><ul><li><strong>Site Key</strong>: Extracted from the Turnstile widget wrapper or specified manually.</li><li><strong>Action Type</strong>: Inserts the returned verification token into the Turnstile response input.</li></ul><h3 id="_3-image-to-text-imagetotext" tabindex="-1">3. Image-to-Text (<code>ImageToText</code>) <a class="header-anchor" href="#_3-image-to-text-imagetotext" aria-label="Permalink to “3. Image-to-Text (ImageToText)”">​</a></h3><p>Designed for standard alphanumeric or mathematical image captchas:</p><table tabindex="0"><thead><tr><th>Image Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Set Image Base64</strong></td><td>Direct Base64 data string input instead of extracting from an <code>&lt;img&gt;</code> element.</td></tr><tr><td><strong>Phrase</strong></td><td>When ON, indicates the answer contains multiple space-separated words.</td></tr><tr><td><strong>Case Sensitive</strong></td><td>Enforces exact uppercase/lowercase distinction.</td></tr><tr><td><strong>Requires Calculation</strong></td><td>Informs solvers that the image contains a math problem (e.g., <code>12 + 5 = ?</code>).</td></tr><tr><td><strong>Numeric Requirements</strong></td><td>Filters allowed characters (<code>Numbers only</code>, <code>Letters only</code>, or <code>Mixed</code>).</td></tr><tr><td><strong>Min / Max Length</strong></td><td>Constrains expected solution string length.</td></tr><tr><td><strong>Comment / Instructions</strong></td><td>Additional hints for human solvers (e.g., &quot;Enter red characters only&quot;).</td></tr></tbody></table><hr><h2 id="api-key-hierarchy" tabindex="-1">API Key Resolution Hierarchy <a class="header-anchor" href="#api-key-hierarchy" aria-label="Permalink to “API Key Resolution Hierarchy”">​</a></h2><p>The extension resolves the 2Captcha API key in the following order of precedence:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Field Level Key]  ──&gt;  [Site Settings Key]  ──&gt;  [Global Settings Key]</span></span>
<span class="line"><span>   (Highest)                                          (Fallback)</span></span></code></pre></div><ol><li><strong>Field Settings</strong>: Configured specifically on this field.</li><li><strong>Site Settings</strong>: Configured in <a href="/documentation/site/site-settings.html">Site Settings</a> for domain-wide usage.</li><li><strong>Global Settings</strong>: Configured in <a href="/documentation/settings.html">Extension Settings</a> across all sites.</li></ol><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-solving-google-recaptcha-v2" tabindex="-1">Example 1: Solving Google reCAPTCHA v2 <a class="header-anchor" href="#example-1-solving-google-recaptcha-v2" aria-label="Permalink to “Example 1: Solving Google reCAPTCHA v2”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Captcha Type: RecaptchaV2TaskProxyless</span></span>
<span class="line"><span>Timeout: 3 minutes</span></span>
<span class="line"><span>Run Action After Solved: ON</span></span>
<span class="line"><span>Action Type: Set Token in reCAPTCHA Field</span></span>
<span class="line"><span>Field Selector Address: #g-recaptcha-response</span></span></code></pre></div><h3 id="example-2-solving-cloudflare-turnstile" tabindex="-1">Example 2: Solving Cloudflare Turnstile <a class="header-anchor" href="#example-2-solving-cloudflare-turnstile" aria-label="Permalink to “Example 2: Solving Cloudflare Turnstile”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Captcha Type: TurnstileTaskProxyless</span></span>
<span class="line"><span>Set Custom Captcha Site Key: ON</span></span>
<span class="line"><span>Captcha Site Key: 0x4AAAAAAAJcZVRqyHh71UMI</span></span>
<span class="line"><span>Timeout: 5 minutes</span></span>
<span class="line"><span>Run Action After Solved: ON</span></span></code></pre></div><h3 id="example-3-solving-math-image-captcha" tabindex="-1">Example 3: Solving Math Image Captcha <a class="header-anchor" href="#example-3-solving-math-image-captcha" aria-label="Permalink to “Example 3: Solving Math Image Captcha”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Field Selector Query (Image Element): img#captcha-img</span></span>
<span class="line"><span>Captcha Type: ImageToText</span></span>
<span class="line"><span>Requires Calculation: ON</span></span>
<span class="line"><span>Numeric: Answer should contain only numbers</span></span>
<span class="line"><span>Run Action After Solved: ON</span></span>
<span class="line"><span>Action Type: Set Captcha Text in Field</span></span>
<span class="line"><span>Field Selector Address: input[name=&quot;captcha_answer&quot;]</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><h3 id="do-s" tabindex="-1">Do&#39;s <a class="header-anchor" href="#do-s" aria-label="Permalink to “Do&#39;s”">​</a></h3><ul><li><strong>Maintain Account Balance</strong>: Ensure your 2Captcha balance has sufficient funds to avoid solution timeouts.</li><li><strong>Set Realistic Timeouts</strong>: Allow at least <code>3</code> to <code>5</code> minutes for complex image captchas.</li><li><strong>Test Target Selectors</strong>: Confirm the selector for <code>#g-recaptcha-response</code> exists in the DOM before running full form workflows.</li><li><strong>Store Solution Tokens</strong>: Enable <strong>Store Token in Variable</strong> if your form requires passing the token across multiple wizard steps.</li></ul><h3 id="don-ts" tabindex="-1">Don&#39;ts <a class="header-anchor" href="#don-ts" aria-label="Permalink to “Don&#39;ts”">​</a></h3><ul><li><strong>Do Not Use Overly Short Timeouts</strong>: Avoid setting timeouts below 1 minute.</li><li><strong>Do Not Hardcode Keys in Templates</strong>: Keep API keys in Global or Site settings when sharing site configurations.</li><li><strong>Do Not Leave Selector Empty</strong>: Always provide a valid <strong>Field Selector Address</strong> to receive the solution.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Request fails with ZERO_BALANCE</strong></td><td>2Captcha account exhausted</td><td>Add balance in your 2Captcha dashboard.</td></tr><tr><td><strong>Timeout error occurred</strong></td><td>Solver traffic high or timeout too strict</td><td>Increase timeout setting to 5–7 minutes.</td></tr><tr><td><strong>Token not triggering form submission</strong></td><td>Missing native change event dispatch</td><td>Add a <a href="/documentation/form-fields/field-settings.html#trigger-javascript-event">Trigger Javascript Event</a> (<code>change</code>, <code>input</code>) on the target element.</td></tr><tr><td><strong>Image captcha rejected</strong></td><td>Low image contrast or unescaped noise</td><td>Provide hints in <strong>Comment</strong> or specify exact <strong>Numeric</strong> character filters.</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/form-fields/field.html">Form Fields Overview</a></li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a></li><li><img src="/svg/beaker.svg" class="doc-icon"> <a href="/documentation/logs.html">Execution Logs</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/segment.html">Segments Automation</a></li></ul>`,44)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};